                if verbose:
                    print(f"    ({cr},{cc}) -> ({nr},{nc}): OUT OF ROW BOUNDS")
                continue

            if nc < 0 or nc >= row_cols:
                if verbose:
                    print(f"    ({cr},{cc}) -> ({nr},{nc}): OUT OF COL BOUNDS (row {nr} has {row_cols} cols)")
                continue

            # Now we can safely access
            if grid[nr][nc] == 2 and (nr, nc) not in visited:
