def connect_to_col0(grid, r, c, target, verbose=False):
    """Check if cell (r,c) with value target can reach col 0 via path of 2s"""
    if grid[r][c] != target:
        if verbose:
            print(f"  Cell ({r},{c}) = {grid[r][c]}, not {target}")
        return False

    q = [(r, c)]
    visited = {(r, c)}

    if verbose:
        print(f"  Starting BFS from {r},{c}")

    while q:
        cr, cc = q.pop(0)

        if cc == 0:
            if verbose:
                print(f"    Reached column 0 at ({cr}, {cc})")
            return True

        row_cols = len(grid[cr])

        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = cr + dr, cc + dc

            if nr < 0 or nr >= len(grid):
                if verbose:
                    print(f"    ({cr},{cc}) -> ({nr},{nc}): OUT OF ROW BOUNDS")
                continue

            if nc < 0 or nc >= row_cols:
                if verbose:
                    print(f"    ({cr},{cc}) -> ({nr},{nc}): OUT OF COL BOUNDS")
                continue

            # Get the neighbor row's column length
            neighbor_row_cols = len(grid[nr])

            if nc < 0 or nc >= neighbor_row_cols:
                if verbose:
                    print(f"    ({cr},{cc}) -> ({nr},{nc}): Oops, wrong len check!")
                continue

            # NOW WE'RE GOOD TO ACCESS
            if grid[nr][nc] == 2 and (nr, nc) not in visited:
                if verbose:
                    print(f"    ({cr},{cc}) -> ({nr},{nc}): adding 2")
                visited.add((nr, nc))
                q.append((nr, nc))

    return False

